# COPY — generated by build_repo_mirror.R. Do not edit here. Working copy: data_workspace_2026-07/ch3_pipeline_restored/scripts/64c_hansard_validation.R
# 64c_hansard_validation.R
# Validation of self-regarding speech measure (scripts 64/64b)
#
# Three tests:
#   1. Dictionary robustness — remove borderline terms ("i believe/think/feel")
#      and re-run. Does the U-shape pattern survive?
#   2. Frontbench confound — proxy backbenchers as speeches with zero
#      positional-term hits. Does U-shape hold for backbenchers only?
#   3. Face validity — top/bottom 20 MPs by mean self-regard score;
#      named MPs (Blair, Thatcher/Major era, Johnson-era).
#
# OUTPUT: console + figures/ch3_hansard_validation.png

if (!require("pacman")) install.packages("pacman")
pacman::p_load(dplyr, ggplot2, readr, stringr, purrr, patchwork, tibble)

.ROOT <- local({
  a <- commandArgs(trailingOnly = FALSE)
  m <- grep("^--file=", a, value = TRUE)
  if (length(m) == 1) normalizePath(file.path(dirname(sub("^--file=", "", m)), ".."))
  else getwd()
})  # portable project root: works via Rscript from anywhere, or falls back to
    # getwd() when sourced interactively (assumes ch3_pipeline_restored/ as cwd)
PROJECT  <- .ROOT
DATA_IN  <- file.path(PROJECT, "data/dataverse_files/Corp_HouseOfCommons_V2.rds")
FIG_OUT  <- file.path(PROJECT, "figures/ch3_hansard_validation.png")

NAVY <- "#1F3864"
RED  <- "#d7191c"
GREY <- "#888888"

# ============================================================
# 1. LOAD AND PREPARE (same filter as 64b)
# ============================================================
cat("Loading ParlSpeech...\n")
parl_raw <- readRDS(DATA_IN)

set.seed(42)
parl_sample <- parl_raw |>
  mutate(date = as.Date(date),
         year = as.integer(format(date, "%Y"))) |>
  filter(date >= as.Date("1988-01-01"),
         date <= as.Date("2019-12-31"),
         nchar(text) > 300) |>
  group_by(year) |>
  group_modify(~ slice_sample(.x, n = min(1500, nrow(.x)))) |>
  ungroup()

cat(sprintf("Sample: %d speeches, %d years\n", nrow(parl_sample), n_distinct(parl_sample$year)))

# ============================================================
# 2. DICTIONARIES — original and stripped version
# ============================================================

# Original career terms (22)
career_full <- c(
  "my role", "my position", "my appointment", "my department",
  "my portfolio", "my responsibilities", "my tenure", "my office",
  "my capacity", "my ministerial", "my shadow", "my career",
  "as minister", "as secretary of state", "as chancellor",
  "as home secretary", "as foreign secretary", "as prime minister",
  "in my view", "i believe", "i think", "i feel"
)

# Positional terms only (genuine frontbench markers, 17 terms)
career_positional <- c(
  "my role", "my position", "my appointment", "my department",
  "my portfolio", "my responsibilities", "my tenure", "my office",
  "my capacity", "my ministerial", "my shadow", "my career",
  "as minister", "as secretary of state", "as chancellor",
  "as home secretary", "as foreign secretary", "as prime minister"
)

# Borderline opinion terms being dropped (4 terms)
career_borderline <- c("in my view", "i believe", "i think", "i feel")

# Policy terms (unchanged)
policy_terms <- c(
  "my constituents", "my constituency", "people in my",
  "the evidence", "the research shows", "the data",
  "the public", "communities", "families",
  "workers", "businesses", "this policy", "the policy",
  "the bill", "the legislation", "the government must",
  "we must", "we should", "we need to"
)

score_speech <- function(text, terms) {
  text_lower <- tolower(text)
  sum(str_count(text_lower, fixed(terms)))
}

cat("\nScoring all speeches (may take a few minutes)...\n")
t0 <- Sys.time()

parl_scored <- parl_sample |>
  mutate(
    n_words        = str_count(text, "\\S+"),
    n_career_full  = map_int(text, score_speech, career_full),
    n_career_pos   = map_int(text, score_speech, career_positional),
    n_career_bord  = map_int(text, score_speech, career_borderline),
    n_policy       = map_int(text, score_speech, policy_terms),
    # Original ratio (full dictionary)
    ratio_full     = (n_career_full + 0.5) / (n_career_full + n_policy + 1),
    # Stripped ratio (positional only, borderline removed)
    ratio_stripped = (n_career_pos  + 0.5) / (n_career_pos  + n_policy + 1)
  ) |>
  filter(n_words >= 50)

cat(sprintf("Scored in %.1f min\n", as.numeric(Sys.time() - t0, units = "mins")))

# ============================================================
# 3. TEST 1 — Dictionary robustness
# ============================================================
annual_compare <- parl_scored |>
  group_by(year) |>
  summarise(
    ratio_full     = mean(ratio_full),
    ratio_stripped = mean(ratio_stripped),
    n              = n(),
    .groups        = "drop"
  )

cat("\n=== TEST 1: Full vs stripped dictionary ===\n")
cat("Correlation between full and stripped annual series: ",
    round(cor(annual_compare$ratio_full, annual_compare$ratio_stripped), 3), "\n")
cat("Mean difference (full - stripped): ",
    round(mean(annual_compare$ratio_full - annual_compare$ratio_stripped), 4), "\n")
print(annual_compare |> select(year, ratio_full, ratio_stripped) |> print(n = 35))

# ============================================================
# 4. TEST 2 — Frontbench confound
# ============================================================
# Proxy backbenchers: speeches with ZERO positional-term hits
# (no "as minister", "my department" etc.)
# These are almost certainly backbench contributions.

backbench_proxy <- parl_scored |>
  filter(n_career_pos == 0)  # no positional terms at all

cat(sprintf("\n=== TEST 2: Frontbench confound ===\n"))
cat(sprintf("All speeches: %d\n", nrow(parl_scored)))
cat(sprintf("Backbench proxy (zero positional hits): %d (%.1f%%)\n",
            nrow(backbench_proxy),
            100 * nrow(backbench_proxy) / nrow(parl_scored)))

annual_backbench <- backbench_proxy |>
  group_by(year) |>
  summarise(
    ratio_backbench = mean(ratio_full),
    n_bb            = n(),
    .groups         = "drop"
  )

annual_all <- annual_compare |>
  left_join(annual_backbench, by = "year")

cat("\nCorrelation full vs backbench-proxy annual series:",
    round(cor(annual_all$ratio_full, annual_all$ratio_backbench, use = "complete"), 3), "\n")

# Does the U-shape hold for backbenchers?
cat("\nBackbench proxy means by period:\n")
annual_all |>
  mutate(period = case_when(
    year <= 1997 ~ "1988-97",
    year <= 2009 ~ "1998-09",
    TRUE         ~ "2010-19"
  )) |>
  group_by(period) |>
  summarise(mean_full = mean(ratio_full),
            mean_bb   = mean(ratio_backbench, na.rm = TRUE),
            .groups = "drop") |>
  print()

# ============================================================
# 5. TEST 3 — Face validity: top/bottom MPs
# ============================================================
# Need speaker column — check if it exists
cat("\nParlSpeech columns:", paste(names(parl_scored), collapse = ", "), "\n")

if ("speaker" %in% names(parl_scored)) {
  mp_scores <- parl_scored |>
    filter(!is.na(speaker), speaker != "") |>
    group_by(speaker) |>
    summarise(
      n_speeches   = n(),
      mean_ratio   = mean(ratio_full),
      mean_stripped = mean(ratio_stripped),
      years_active = paste(min(year), max(year), sep = "-"),
      .groups      = "drop"
    ) |>
    filter(n_speeches >= 20) |>   # min 20 speeches for reliability
    arrange(desc(mean_ratio))

  cat("\n=== TEST 3: Top 20 most self-regarding MPs (≥20 speeches) ===\n")
  print(mp_scores |> head(20) |> select(speaker, n_speeches, mean_ratio, years_active))

  cat("\n=== Bottom 20 least self-regarding MPs ===\n")
  print(mp_scores |> tail(20) |> select(speaker, n_speeches, mean_ratio, years_active))

  # Named MP check
  named_check <- c("Blair", "Brown", "Thatcher", "Major", "Cameron",
                   "Johnson", "May", "Corbyn", "Miliband", "Hague")
  cat("\n=== Named MP scores ===\n")
  for (nm in named_check) {
    hits <- mp_scores |> filter(str_detect(speaker, regex(nm, ignore_case = TRUE)))
    if (nrow(hits) > 0) {
      cat(sprintf("  %s: mean_ratio=%.3f (n=%d speeches, %s)\n",
                  hits$speaker[1], hits$mean_ratio[1],
                  hits$n_speeches[1], hits$years_active[1]))
    } else {
      cat(sprintf("  %s: not found\n", nm))
    }
  }
} else {
  cat("No 'speaker' column in scored data — face validity check skipped.\n")
}

# ============================================================
# 6. VALIDATION FIGURE
# ============================================================
long_annual <- annual_all |>
  tidyr::pivot_longer(
    cols      = c(ratio_full, ratio_stripped, ratio_backbench),
    names_to  = "series",
    values_to = "value"
  ) |>
  mutate(series = recode(series,
    "ratio_full"      = "Full dictionary (22 terms)",
    "ratio_stripped"  = "Positional only (18 terms,\nborderline removed)",
    "ratio_backbench" = "Backbench proxy\n(zero positional hits)"
  ))

p_val <- ggplot(long_annual, aes(x = year, y = value, colour = series, linetype = series)) +
  geom_line(linewidth = 0.9) +
  scale_colour_manual(values = c(
    "Full dictionary (22 terms)"           = NAVY,
    "Positional only (18 terms,\nborderline removed)" = "#e08214",
    "Backbench proxy\n(zero positional hits)" = "#1b7837"
  ), name = NULL) +
  scale_linetype_manual(values = c(
    "Full dictionary (22 terms)"           = "solid",
    "Positional only (18 terms,\nborderline removed)" = "dashed",
    "Backbench proxy\n(zero positional hits)" = "dotdash"
  ), name = NULL) +
  scale_x_continuous(breaks = seq(1990, 2020, 5)) +
  scale_y_continuous(labels = scales::percent_format(accuracy = 0.1)) +
  labs(
    title    = "Validation: self-regarding speech ratio — three dictionary/sample variants",
    subtitle = paste0(
      "If the U-shape (Blair dip, post-2010 recovery) holds across all three, ",
      "it is not driven by borderline terms or frontbench composition.\n",
      "Backbench proxy = speeches with zero positional-term hits (no 'as minister', 'my department' etc.)."
    ),
    x = NULL, y = "Self-regarding ratio (mean per year)"
  ) +
  theme_bw(base_size = 11) +
  theme(
    plot.title         = element_text(face = "bold", colour = NAVY, size = 11),
    plot.subtitle      = element_text(colour = GREY, size = 8, lineheight = 1.3),
    panel.grid.minor   = element_blank(),
    panel.grid.major.x = element_blank(),
    axis.text.x        = element_text(angle = 45, hjust = 1),
    legend.position    = "top",
    legend.text        = element_text(size = 8.5),
    legend.key.width   = unit(1.4, "cm")
  )

ggsave(FIG_OUT, p_val, width = 10, height = 6, dpi = 300)
cat("\nValidation figure saved:", FIG_OUT, "\n")
cat("\nSUMMARY:\n")
cat("If all three lines show the same U-shape, the pattern is robust.\n")
cat("If stripped/backbench lines flatten, the Blair dip was a frontbench/opinion-term artefact.\n")
